<?php
declare(strict_types=1);
function onlineSetFriendlyFire(PDO $db,array &$records,array &$pending,array $table,array $identity,array $arguments,bool $isGm):array {
 if(!is_bool($arguments['enabled']??null))rejectOnlineCommand($db,400,'Le réglage Friendly fire doit être coché ou décoché.','friendly_fire_invalid');$sceneId=(string)($arguments['sceneId']??'');$tokenId=(string)($arguments['tokenId']??'');if(!$isGm&&$sceneId!==onlineActiveSceneId($table))rejectOnlineCommand($db,409,'La scène de cette unité a changé.','stale_scene');
 $key=onlineTokenDomainKey($sceneId,$tokenId);$records=array_replace($records,applicationDomainRecords($db,[$key]));$token=applicationDomainPayload($records,$key);if($token===[])rejectOnlineCommand($db,404,'Cette unité n’existe plus.','token_missing');
 if(!$isGm&&onlineTokenControllerIdFromRecords($db,$records,$token)!==($identity['id']??''))rejectOnlineCommand($db,403,'Cette unité ne vous appartient pas.','unit_not_owned');$enabled=$arguments['enabled'];$changed=($token['friendlyFire']??false)!==$enabled;
 if(unitUsesCharacterSheet($token)){$characterId=$token['characterId'];$characterKey='character:'.$characterId;$records=array_replace($records,applicationDomainRecords($db,[$characterKey]));$character=applicationDomainPayload($records,$characterKey);$changed=($character['friendlyFire']??false)!==$enabled;$character['friendlyFire']=$enabled;if($changed)$character['_updatedAt']=(int)floor(microtime(true)*1000);queueOnlineDomainUpsert($pending,$records,$characterKey,$character);$occurrences=applicationCharacterTokenDomainRecords($db,$characterId);$records=array_replace($records,$occurrences);foreach($occurrences as$k=>$record){$t=applicationDomainPayload($records,$k);if(unitUsesCharacterSheet($t)&&$t['characterId']===$characterId)queueOnlineDomainUpsert($pending,$records,$k,[...$t,'friendlyFire'=>$enabled,'_updatedAt'=>$character['_updatedAt']??($t['_updatedAt']??0)]);}}
 else queueOnlineDomainUpsert($pending,$records,$key,[...$token,'friendlyFire'=>$enabled,'_updatedAt'=>(int)floor(microtime(true)*1000)]);return ['tokenId'=>$tokenId,'sceneId'=>$sceneId,'friendlyFire'=>$enabled,'changed'=>$changed];
}
